        # parte 2 — Dios, el mejor de los mundos y el espacio
        ch(2, "¿Quién lo dijo?", "«El alma sigue sus propias leyes y el cuerpo también las suyas, y se encuentran en virtud de la armonía preestablecida.»", "Leibniz",
           ["Leibniz", "Spinoza", "Malebranche"], "*Monadología* § 78. Malebranche era ocasionalista: Dios interviene en cada ocasión."),
        ap(ch(2, "¿Influjo, asistencia o armonía?", "Dios mueve el brazo cada vez que el alma quiere moverlo.", "asistencia (ocasionalismo)",
           ["asistencia (ocasionalismo)", "influjo", "armonía preestablecida"],
           "Es el relojero que ajusta los relojes a cada momento: Malebranche. Leibniz lo rechaza como un milagro perpetuo.")),
        ap(ch(2, "¿Influjo, asistencia o armonía?", "El alma mueve el cuerpo a través de la glándula pineal.", "influjo",
           ["influjo", "asistencia (ocasionalismo)", "armonía preestablecida"],
           "Es Descartes (semana 47): un reloj mueve al otro. Para Leibniz es imposible, porque las sustancias no tienen ventanas.")),
        ap(ch(2, "¿Influjo, asistencia o armonía?", "Dos relojes tan bien hechos desde el principio que marcan siempre la misma hora sin tocarse.", "armonía preestablecida",
           ["armonía preestablecida", "influjo", "asistencia (ocasionalismo)"],
           "La imagen de la *Segunda aclaración del Nuevo sistema* (1696).")),
        ap(ch(2, "¿Leibniz o Spinoza?", "«El alma y el cuerpo son dos sustancias distintas que concuerdan porque Dios las coordinó.»", "Leibniz",
           ["Leibniz", "Spinoza"],
           "Para Spinoza (semana 49) son una sola cosa bajo dos atributos (E2P7): no hay nada que coordinar.")),
        ap(ch(2, "¿Leibniz o Spinoza?", "«Las almas obran según causas finales; los cuerpos, según causas eficientes, y los dos reinos concuerdan.»", "Leibniz",
           ["Leibniz", "Spinoza"],
           "*Monadología* § 79. Spinoza había declarado ficción a las causas finales (*Ética* I, apéndice).")),
        cz(2, "Completá.", "Cada mónada es un ___ viviente perpetuo del universo.", "espejo",
           [], "*Monadología* § 56. Y la ciudad vista desde distintos lados (§ 57): cada una es una perspectiva sobre el mismo universo."),
        ch(2, "Elegí.", "Según el § 55, ¿por qué existe el mejor de los mundos?", "la sabiduría de Dios lo conoce, su bondad lo elige y su poder lo produce",
           ["la sabiduría de Dios lo conoce, su bondad lo elige y su poder lo produce", "es el único posible", "Dios lo eligió al azar"],
           "Hay infinitos mundos posibles en el entendimiento de Dios (§ 53); la razón de la elección es el grado de perfección (§ 54)."),
        ap(ch(2, "¿Qué diría Leibniz?", "«Si hay terremotos, este no puede ser el mejor de los mundos posibles.»", "que un mundo sin esos males sería, en conjunto, peor",
           ["que un mundo sin esos males sería, en conjunto, peor", "que los terremotos no existen", "que Dios no pudo evitarlos por falta de poder"],
           "El mejor no es el que no tiene males, sino el que combina la mayor variedad con el mayor orden (§ 58; *Teodicea* § 8).")),
        ap(ch(2, "¿Qué tipo de mal es?", "Un terremoto que destruye una ciudad.", "físico",
           ["físico", "moral", "metafísico"],
           "*Teodicea* § 21: el mal físico es el sufrimiento; el moral, el pecado; el metafísico, la imperfección de lo creado.")),
        ap(ch(2, "¿Qué tipo de mal es?", "Que ninguna criatura sea infinita ni perfecta.", "metafísico",
           ["metafísico", "físico", "moral"],
           "Es la raíz de los otros dos: lo creado es limitado porque no es Dios.")),
        ap(ch(2, "¿Hombre de paja o crítica justa?", "«Para Leibniz, todo está bien y el mal no existe.»", "hombre de paja",
           ["hombre de paja", "crítica justa"],
           "Leibniz reconoce tres clases de mal. Es la versión de Pangloss en *Cándido*. Una crítica justa preguntaría cómo sabe Leibniz que este mundo es el mejor.")),
        ch(2, "¿Quién lo dijo?", "«Todo es para lo mejor en el mejor de los mundos posibles.»", "Pangloss, el personaje de Voltaire",
           ["Pangloss, el personaje de Voltaire", "Leibniz, en la *Monadología*", "Spinoza, en la *Ética*"],
           "*Cándido* (1759), cap. 1 y siguientes: la frase es una parodia; no está en Leibniz. Es la trampa más famosa sobre él."),
        ap(ch(2, "¿Qué tesis de la semana satiriza?", "En *Cándido*, Pangloss explica que la nariz se hizo para llevar anteojos, y por eso tenemos anteojos.", "el mejor de los mundos y la razón suficiente usada a ciegas",
           ["el mejor de los mundos y la razón suficiente usada a ciegas", "la identidad de los indiscernibles", "el argumento del molino"],
           "Voltaire, *Cándido*, cap. 1. Es, además, el error que Spinoza llamaba finalismo (semana 49): tomar el efecto por la causa.")),
        ch(2, "Elegí.", "¿Qué catástrofe usa Voltaire contra el optimismo, en *Cándido* y en un poema de 1756?", "el terremoto de Lisboa de 1755",
           ["el terremoto de Lisboa de 1755", "la peste de Londres de 1665", "el incendio de Roma"],
           "*Poema sobre el desastre de Lisboa* (1756) y *Cándido*, cap. 5. Lo vas a ver con la Ilustración francesa (semana 58)."),
        ch(2, "Elegí.", "¿Contra quién escribió Leibniz los *Ensayos de teodicea* (1710)?", "contra Pierre Bayle, que veía insoluble el problema del mal",
           ["contra Pierre Bayle, que veía insoluble el problema del mal", "contra Spinoza, que ya había muerto", "contra Voltaire"],
           "Bayle, en su *Diccionario*, sostenía que la razón no puede conciliar el mal con un Dios bueno. Voltaire escribió después, contra Leibniz."),
        ap(ch(2, "¿Newton o Leibniz?", "«Si sacaras todos los cuerpos del universo, seguiría habiendo espacio.»", "Newton",
           ["Newton", "Leibniz"],
           "Espacio absoluto. Para Leibniz, sin cosas no hay orden de coexistencias y, por lo tanto, no hay espacio.")),
        ap(ch(2, "¿Qué principio usa?", "«Si el espacio fuera absoluto, Dios no tendría razón para poner el mundo aquí y no tres metros más allá.»", "el de razón suficiente, con el de los indiscernibles",
           ["el de razón suficiente, con el de los indiscernibles", "el de contradicción", "el del mejor de los mundos solamente"],
           "Tercera carta a Clarke, § 5: las dos situaciones serían indiscernibles, y Dios no puede elegir sin razón.")),
        ch(2, "¿Quién lo dijo?", "«El espacio es un orden de coexistencias, así como el tiempo es un orden de sucesiones.»", "Leibniz",
           ["Leibniz", "Newton", "Kant"], "Tercera carta a Clarke, § 4, en resumen. Para Kant (semana 62) espacio y tiempo serán formas de la intuición."),
        ap(ch(2, "¿Qué dilema plantea?", "Si Dios eligió el mejor mundo porque es el mejor, ¿podía no elegirlo?", "que la elección del mejor parece necesaria y Leibniz se acercaría a Spinoza",
           ["que la elección del mejor parece necesaria y Leibniz se acercaría a Spinoza", "que Dios no existe", "que el mundo no tiene razón suficiente"],
           "Leibniz responde que Dios elige el mejor con necesidad moral, no metafísica: elegir otro no implica contradicción.")),
